import os # Keep the validation-driven refinement within one CPU worker.
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1' # Bound BLAS and PyTorch oversubscription.
import copy,json,time # Retain initial model lineage and independent refinement checkpoints.
import numpy as np # Construct physical geometric descriptors and displacement-difference supervision.
import torch # Continue the shared operator without introducing family-specific parameters.
from unified_graph import SharedOperator,features,batch,forward,full_prediction,OUT,RUN,FAMILIES,write_json,sha # Reuse exact source inputs and variable-topology architecture.
torch.set_num_threads(1) # Share resources with other simulation work.
def enhanced(item): # Add physically meaningful occupancy and cross-section descriptors absent in the first coarse encoder.
    sample=features(item);raw=np.load(RUN/'cases'/item['id']/'fields.npz');xyz=raw['xyz'];normalized=(xyz-xyz.min(axis=0))/np.maximum(np.ptp(xyz,axis=0),1e-12);tet=raw['tet'];volume=raw['volume'];inverse=sample['inverse'];nodal_volume=np.zeros(len(xyz));neighbor=np.arange(len(xyz)) # Read only geometry, topology and material-volume inputs.
    for nodes,v in zip(tet,volume): nodal_volume[nodes]+=v/10;neighbor[nodes]=np.roll(nodes,1) # Build source-element adjacency and descriptive nodal tributary volumes without using response labels.
    descriptors=np.zeros((36,7),np.float32) # Encode occupancy and six dimensionless spatial covariance entries per real coarse region.
    for region in range(sample['coarse_count']): # Distinguish volume distribution and local cross-section geometry within coarse graph bins.
        selected=inverse==region;weights=nodal_volume[selected];positions=normalized[selected];center=np.average(positions,axis=0,weights=weights);delta=positions-center;cov=(delta*weights[:,None]).T@delta/max(weights.sum(),1e-30);descriptors[region]=np.r_[weights.sum()/max(nodal_volume.sum(),1e-30)*36,cov[np.triu_indices(3)]*100] # Preserve affine geometry information missing from simple node means.
    sample['query']=np.column_stack([sample['query'],descriptors[inverse]]).astype(np.float32);sample['coarse']=np.column_stack([sample['coarse'],descriptors]).astype(np.float32);sample['neighbor']=neighbor # Supply added geometry to both shared encoder and point decoder.
    return sample # Retain exact fixed split identity and unchanged FEM target.
def initialize(checkpoint,new_size): # Extend old learned input layers with zero-initialized new geometry channels.
    model=SharedOperator(new_size);old=checkpoint['state_dict'];new=model.state_dict();old_size=checkpoint['features_size'] # Preserve the original validation-selected model at refinement epoch zero.
    for key,value in new.items(): # Copy every compatible shared parameter exactly.
        if key not in ['encoder.0.weight','query_encoder.weight','decoder.0.weight']: value.copy_(old[key]) # Leave no family-specific reset or test-informed initializer.
        else: # Insert additional input features without shifting learned latent-channel semantics.
            value.zero_();value[:,:old_size]=old[key][:,:old_size] # Preserve original physical input coefficients.
            if key=='decoder.0.weight': value[:,new_size:]=old[key][:,old_size:] # Preserve local/global/attention latent coefficients after the expanded query block.
    model.load_state_dict(new);return model # Start from mathematically identical old predictions before learning new descriptors.
def paired_batch(samples,ids,rng): # Supervise both displacement fields and actual within-element displacement differences.
    selected=[samples[i] for i in ids];indices=[rng.integers(0,s['node_count'],128) for s in selected];pairs=[np.r_[ix,s['neighbor'][ix]] for s,ix in zip(selected,indices)];result={key:torch.tensor(np.stack([s[key] for s in selected])) for key in ['coarse','adj','mask']} # Sample physical node pairs through true source elements.
    for key in ['query','inverse','distance','target']: result[key]=torch.tensor(np.stack([s[key][ix] for s,ix in zip(selected,pairs)])) # Keep both endpoints aligned with exact field labels.
    result['denominator']=torch.tensor([max(s['target_mse'],1e-20) for s in selected],dtype=torch.float32);return result # Retain equal-case normalization independent of structural family response magnitude.
def main(): # Refine the first shared all-family model based only on its validation diagnosis.
    samples=[enhanced(item) for item in json.loads((RUN/'manifest.json').read_text())];train=[i for i,s in enumerate(samples) if s['split']=='train'];validation=[i for i,s in enumerate(samples) if s['split']=='validation'];source=OUT/'all_families/seed_17/model.pt';checkpoint=torch.load(source,weights_only=False);model=initialize(checkpoint,samples[0]['query'].shape[1]);optimizer=torch.optim.AdamW(model.parameters(),lr=.0007,weight_decay=1e-6);epochs=400;scheduler=torch.optim.lr_scheduler.CosineAnnealingLR(optimizer,epochs,eta_min=1e-5);rng=np.random.default_rng(117);torch.manual_seed(117);best=None;best_score=float('inf');history=[];directory=OUT/'refined_all_families';directory.mkdir(exist_ok=True);started=time.time();validation_batches=[batch(samples,validation[i:i+8],np.random.default_rng(999+i),256) for i in range(0,len(validation),8)] # Freeze same geometry splits while adding shape descriptors and gradient-sensitive supervision.
    for epoch in range(epochs): # Execute actual continuation updates rather than changing only evaluation settings.
        model.train();order=rng.permutation(train);losses=[] # Retain every training geometry in each epoch.
        for start in range(0,len(order),16): # Bound paired-query memory and gradient computation.
            b=paired_batch(samples,order[start:start+16],rng);optimizer.zero_grad();prediction=forward(model,b);data_loss=((prediction-b['target']).square().mean(dim=(1,2))/b['denominator']).mean();pred_difference=prediction[:,:128]-prediction[:,128:];true_difference=b['target'][:,:128]-b['target'][:,128:];difference_loss=((pred_difference-true_difference).square().mean(dim=(1,2))/b['denominator']).mean();loss=data_loss+.2*difference_loss;loss.backward();torch.nn.utils.clip_grad_norm_(model.parameters(),2.);optimizer.step();losses.append([float(data_loss.detach()),float(difference_loss.detach())]) # Improve within-element variation without calling it a complete equilibrium loss.
        scheduler.step() # Follow a fixed continuation schedule selected before new test evaluation.
        if epoch%10==0 or epoch==epochs-1: # Keep checkpoint decisions validation-only.
            model.eval() # Freeze model state for validation.
            with torch.no_grad():score=float(torch.cat([((forward(model,b)-b['target']).square().mean(dim=(1,2))/b['denominator']).sqrt() for b in validation_batches]).mean()) # Evaluate unchanged validation cases and deterministic query subset.
            history.append({'epoch':epoch,'validation_relative':score,'mean_data_loss':float(np.mean(np.array(losses)[:,0])),'mean_difference_loss':float(np.mean(np.array(losses)[:,1]))}) # Preserve actual refinement objective components.
            if score<best_score:best_score=score;best=copy.deepcopy(model.state_dict());best_epoch=epoch # Choose a candidate without examining test cases.
            if epoch%50==0:print('REFINEMENT',epoch,score,flush=True) # Provide concrete continuation progress.
    model.load_state_dict(best);model.eval();torch.save({'state_dict':best,'features_size':samples[0]['query'].shape[1],'selected_epoch':best_epoch,'source_checkpoint_sha256':sha(source),'training_ids':[samples[i]['id'] for i in train],'validation_ids':[samples[i]['id'] for i in validation],'feature_version':'volume-occupancy-and-covariance-v2'},directory/'model.pt');write_json(directory/'history.json',{'history':history,'selected_epoch':best_epoch,'validation_relative':best_score,'seconds':time.time()-started,'changes':['seven input-only geometric occupancy/covariance descriptors','supervision of within-element displacement differences'],'source_checkpoint_sha256':sha(source)}) # Preserve complete optimization lineage.
    from scipy.sparse import load_npz # Load independent full physical operators only for final frozen evaluation.
    rows=[] # Evaluate every original independent and OOD geometry with unchanged reference labels.
    for sample in samples: # Keep original held-out denominators.
        if sample['split'] not in ['test','ood']:continue # Exclude fitting and validation examples from reported independent accuracy.
        with torch.no_grad():predicted=full_prediction(model,sample) # Predict arbitrary original fine-node counts with one shared model.
        path=RUN/'cases'/sample['id'];raw=np.load(path/'fields.npz');K=load_npz(path/'stiffness.npz');f=raw['f'].ravel();free=raw['free'];error=float(np.linalg.norm(predicted-raw['u'])/max(np.linalg.norm(raw['u']),1e-15));residual=float(np.linalg.norm((K@predicted.ravel()-f)[free])/max(np.linalg.norm(f[free]),1e-15));rows.append({'id':sample['id'],'family':sample['family'],'split':sample['split'],'relative_L2':error,'full_equilibrium_relative':residual,'research_gate_pass':error<.05 and residual<.05});np.savez_compressed(directory/(sample['id']+'.npz'),predicted=predicted,reference=raw['u']) # Save every refined raw field without numerical post-correction.
    summary=[{'family':family,'test_cases':sum(r['family']==family and r['split']=='test' for r in rows),'mean_relative_L2':float(np.mean([r['relative_L2'] for r in rows if r['family']==family and r['split']=='test'])),'max_full_equilibrium_relative':float(max(r['full_equilibrium_relative'] for r in rows if r['family']==family and r['split']=='test'))} for family in FAMILIES];write_json(directory/'evaluation.json',{'summary':summary,'cases':rows,'release':'HOLD until independent physical and fidelity gates pass','physical_loss':'supervised within-element displacement difference, not an equilibrium constraint'});print('REFINEMENT_COMPLETE',summary,flush=True) # Report actual success or failure of validation-driven optimization.
if __name__=='__main__':main() # Run only the declared real refinement experiment.
